func sqrtInt(n int) (int, error) {
	if n < 0 {
		return 0, errors.New("manfiy sondan ildiz olib bo'lmaydi")
	}
	r := 0
	for (r+1)*(r+1) <= n {
		r++
	}
	return r, nil
}

func main() {
	for _, n := range []int{49, 50, -4} {
		r, err := sqrtInt(n)
		if err != nil {
			fmt.Println("xato:", err)
			continue
		}
		fmt.Printf("sqrt(%d) ~ %d\n", n, r)
	}
}

