var (
	ErrNotFound   = errors.New("topilmadi")
	ErrPermission = errors.New("ruxsat yo'q")
)

func fetch(kind int) error {
	switch kind {
	case 1:
		return ErrNotFound
	case 2:
		return ErrPermission
	case 3:
		return errors.New("noma'lum nosozlik")
	}
	return nil
}

func main() {
	for kind := 0; kind <= 3; kind++ {
		err := fetch(kind)
		switch {
		case err == nil:
			fmt.Println(kind, "muvaffaqiyat")
		case errors.Is(err, ErrNotFound):
			fmt.Println(kind, "404: resurs yo'q")
		case errors.Is(err, ErrPermission):
			fmt.Println(kind, "403: taqiqlangan")
		default:
			fmt.Println(kind, "500:", err)
		}
	}
}

