import (
	"errors"
	"fmt"
)

func calc(a, b float64, op string) (float64, error) {
	switch op {
	case "+":
		return a + b, nil
	case "-":
		return a - b, nil
	case "*":
		return a * b, nil
	case "/":
		if b == 0 {
			return 0, errors.New("nolga bo'lib bo'lmaydi")
		}
		return a / b, nil
	default:
		return 0, fmt.Errorf("noma'lum amal: %q", op)
	}
}

func main() {
	tests := []struct {
		a, b float64
		op   string
	}{{8, 2, "/"}, {8, 0, "/"}, {3, 4, "^"}, {3, 4, "*"}}

	for _, t := range tests {
		r, err := calc(t.a, t.b, t.op)
		if err != nil {
			fmt.Println("xato:", err)
			continue
		}
		fmt.Printf("%g %s %g = %g\n", t.a, t.op, t.b, r)
	}
}

