type Account struct {
	Owner   string
	Balance int
}

func (a *Account) Withdraw(amount int) error {
	if amount <= 0 {
		return errors.New("summa musbat bo'lishi kerak")
	}
	if amount > a.Balance {
		return fmt.Errorf("yetarli mablag' yo'q: kerak %d, mavjud %d", amount, a.Balance)
	}
	a.Balance -= amount
	return nil
}

func main() {
	acc := &Account{Owner: "Madina", Balance: 100}
	for _, amount := range []int{30, 80, -5, 70} {
		if err := acc.Withdraw(amount); err != nil {
			fmt.Println("rad etildi:", err)
			continue
		}
		fmt.Println("yechildi:", amount, "qoldiq:", acc.Balance)
	}
}

