import (
	"errors"
	"fmt"
)

var ErrEmptyStack = errors.New("stek bo'sh")

type Stack struct{ items []int }

func (s *Stack) Push(v int) { s.items = append(s.items, v) }

func (s *Stack) Pop() (int, error) {
	if len(s.items) == 0 {
		return 0, ErrEmptyStack
	}
	last := len(s.items) - 1
	v := s.items[last]
	s.items = s.items[:last]
	return v, nil
}

func main() {
	var s Stack
	s.Push(1)
	s.Push(2)

	for i := 0; i < 3; i++ {
		v, err := s.Pop()
		if errors.Is(err, ErrEmptyStack) {
			fmt.Println("elementlar tugadi")
			break
		}
		fmt.Println("pop:", v)
	}
}

