	Want    int
}

func (e *InsufficientStockError) Error() string {
	return fmt.Sprintf("%s: omborda %d ta, kerak %d ta", e.Product, e.Have, e.Want)
}

var stock = map[string]int{"olma": 10, "nok": 2}

func order(product string, qty int) error {
	have := stock[product]
	if have < qty {
		return &InsufficientStockError{product, have, qty}
	}
	stock[product] -= qty
	return nil
}

func main() {
	for _, qty := range []int{4, 5} {
