	ErrBadRequest = errors.New("noto'g'ri so'rov")
)

func isRetryable(err error) bool { return errors.Is(err, ErrBusy) }

func call(results []error) func() error {
	i := 0
	return func() error {
		err := results[i]
		i++
		return err
	}
}

func retry(max int, f func() error) (attempts int, err error) {
	for attempts = 1; attempts <= max; attempts++ {
		if err = f(); err == nil || !isRetryable(err) {
			return attempts, err
		}
	}
	return max, err
}

func main() {
	n, err := retry(5, call([]error{ErrBusy, ErrBusy, nil}))
	fmt.Println("urinishlar:", n, "xato:", err)

	n, err = retry(5, call([]error{ErrBusy, ErrBadRequest}))
	fmt.Println("urinishlar:", n, "xato:", err)
}

