			fmt.Println(v, "-> PASS (xato yo'q)")
		case ok && re.Value == v:
			fmt.Printf("%d -> PASS (RangeError, chegara %d..%d)\n", v, re.Min, re.Max)
		default:
			fmt.Println(v, "-> FAIL")
		}
	}
}

