type Kind string

type KindError struct {
	Kind Kind
	Err  error
}

func (e *KindError) Error() string { return string(e.Kind) + ": " + e.Err.Error() }
func (e *KindError) Unwrap() error { return e.Err }

func kindOf(err error) Kind {
	if ke, ok := errors.AsType[*KindError](err); ok {
		return ke.Kind
	}
	return "boshqa"
}

func main() {
	errs := []error{
		&KindError{"tarmoq", errors.New("timeout")},
		&KindError{"validatsiya", errors.New("email bo'sh")},
		fmt.Errorf("sinxronlash: %w", &KindError{"tarmoq", errors.New("reset")}),
		errors.New("noma'lum"),
		&KindError{"validatsiya", errors.New("yosh manfiy")},
		&KindError{"tarmoq", errors.New("refused")},
	}

	counts := map[Kind]int{}
	for _, err := range errs {
		counts[kindOf(err)]++
	}
	for _, k := range slices.Sorted(maps.Keys(counts)) {
		fmt.Printf("%-12s %d\n", k, counts[k])
	}
}

