// oneShot: ma'lumotni va EOF ni bitta Read da qaytaradi
type oneShot struct{ data string }

func (r *oneShot) Read(p []byte) (int, error) {
	if r.data == "" {
		return 0, io.EOF
	}
	n := copy(p, r.data)
	r.data = ""
	return n, io.EOF
}

func main() {
	r := &oneShot{data: "oxirgi qism"}
	buf := make([]byte, 64)

	n, err := r.Read(buf)
	fmt.Printf("n=%d err=%v\n", n, err)
	fmt.Printf("ma'lumot: %q\n", buf[:n]) // err bo'lsa ham, n baytni yo'qotmang
}

