)

type Tx struct{ log []string }

func (t *Tx) Do(op string) { t.log = append(t.log, op) }

func transfer(fail bool) (err error) {
	tx := &Tx{}
	committed := false
	defer func() {
		if !committed {
			fmt.Println("rollback:", tx.log)
		}
	}()

	tx.Do("hisobdan yechish")
	if fail {
		return errors.New("qabul qiluvchi hisob topilmadi")
	}
	tx.Do("hisobga qo'shish")

	fmt.Println("commit:", tx.log)
	committed = true
	return nil
}

func main() {
	fmt.Println(transfer(false))
	fmt.Println(transfer(true))
}

