import (
	"errors"
	"fmt"
	"strconv"
)

func parseAll(lines []string, maxErrors int) ([]int, error) {
	var nums []int
	var errs []error
	for i, line := range lines {
		n, err := strconv.Atoi(line)
		if err != nil {
			errs = append(errs, fmt.Errorf("qator %d: %w", i+1, err))
			if len(errs) >= maxErrors {
				errs = append(errs, errors.New("xatolar ko'pligi uchun to'xtatildi"))
				break
			}
			continue
		}
		nums = append(nums, n)
	}
	return nums, errors.Join(errs...)
}

func main() {
	lines := []string{"1", "a", "3", "b", "5", "c", "7"}
	nums, err := parseAll(lines, 2)
	fmt.Println("o'qilgan:", nums)
	fmt.Println(err)
}

