import (
	"context"
	"errors"
	"fmt"
	"time"
)

func worker(ctx context.Context) error {
	<-ctx.Done()
	return ctx.Err()
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	err := worker(ctx)
	switch {
	case errors.Is(err, context.Canceled):
		fmt.Println("worker to'xtatildi (normal holat)")
	case err != nil:
		fmt.Println("haqiqiy xato:", err)
	}

	ctx2, cancel2 := context.WithTimeout(context.Background(), time.Millisecond)
	defer cancel2()
	err = worker(ctx2)
	fmt.Println("muddat tugadi:", errors.Is(err, context.DeadlineExceeded))
}

