func fetch(ctx context.Context, id int) (string, error) {
	if err := ctx.Err(); err != nil {
		return "", fmt.Errorf("fetch(%d): %w", id, err)
	}
	return "ma'lumot", nil
}

func main() {
	_, err := fetch(context.Background(), 1)
	fmt.Println("oddiy kontekst:", err)

	ctx, cancel := context.WithDeadline(context.Background(), time.Now().Add(-time.Minute))
	defer cancel()

	_, err = fetch(ctx, 2)
	fmt.Println(err)
	fmt.Println("muddat tugagan:", errors.Is(err, context.DeadlineExceeded))

	t, ok := errors.AsType[interface {
		error
		Timeout() bool
	}](err)
	fmt.Println("Timeout() bor:", ok && t.Timeout())
}

