func opErr(op string, err error) error {
	if err == nil {
		return nil
	}
	return fmt.Errorf("%s: %w", op, err)
}

var ErrDisk = errors.New("disk xatosi")

func writeBlock(n int) error {
	if n > 2 {
		return opErr(fmt.Sprintf("writeBlock(%d)", n), ErrDisk)
	}
	return nil
}

func backup() error {
	for i := 1; i <= 4; i++ {
		if err := writeBlock(i); err != nil {
			return opErr("backup", err)
		}
	}
	return nil
}

func main() {
	err := backup()
	fmt.Println(err)
	fmt.Println(errors.Is(err, ErrDisk))
}

