import (
	"errors"
	"fmt"
)

var (
	ErrOutOfStock = errors.New("omborda yo'q")
	ErrPayment    = errors.New("to'lov rad etildi")
)

type OrderError struct {
	ID  int
	Op  string
	Err error
}

func (e *OrderError) Error() string { return fmt.Sprintf("buyurtma #%d: %s: %v", e.ID, e.Op, e.Err) }
func (e *OrderError) Unwrap() error { return e.Err }

func process(id int) error {
	switch {
	case id%3 == 0:
		return &OrderError{id, "band qilish", ErrOutOfStock}
	case id%4 == 0:
		return &OrderError{id, "to'lov", ErrPayment}
	}
	return nil
}

func main() {
	var errs []error
	for id := 1; id <= 8; id++ {
		if err := process(id); err != nil {
			errs = append(errs, err)
		}
	}
	all := errors.Join(errs...)
	fmt.Println(all)
	fmt.Println("ombor:", errors.Is(all, ErrOutOfStock), "| to'lov:", errors.Is(all, ErrPayment))
	if oe, ok := errors.AsType[*OrderError](all); ok {
		fmt.Println("birinchi muammo:", oe.ID, "-", oe.Op)
	}
}

